(function(){
 const api=window.KHALASA_API_BASE_URL||location.origin, labels={'orders.read':'عرض الطلبات','orders.manage':'إسناد وإدارة الطلبات','riders.read':'عرض الكباتن','riders.manage':'تشغيل وإيقاف الكباتن','partners.request':'طلب إضافة محل أو مندوب'};
 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 adminTitles.cityUsers='إدارات المدن';
 document.querySelector('aside nav').insertAdjacentHTML('beforeend','<button data-admin-page="cityUsers" onclick="adminPage(\'cityUsers\',this);loadCityUsers()">♜ <span>إدارات المدن</span></button>');
 document.querySelector('main').insertAdjacentHTML('beforeend',`<section class="admin-page" id="admin-cityUsers"><div class="city-token"><input id="cityAdminToken" type="password" placeholder="رمز دخول المدير الرئيسي"><button class="primary" onclick="saveAdminToken()">حفظ الرمز</button><a class="table-btn" href="city-admin/">فتح لوحة المدينة</a></div><p id="cityApiNote" class="api-note">أدخل رمز دخول المدير الرئيسي للربط بقاعدة البيانات.</p><div class="city-admin-layout"><form class="panel city-form" onsubmit="createCityUser(event)"><div class="panel-head"><div><h2>مستخدم إدارة مدينة</h2><p>كل مستخدم مقيد بمدينة واحدة فقط.</p></div></div><div class="city-form-grid"><label>الاسم الكامل<input id="cityUserName" required></label><label>رقم الهاتف<input id="cityUserPhone" required inputmode="numeric" pattern="01[0-9]{9}" placeholder="01xxxxxxxxx"></label><label>المدينة<select id="citySelect" required><option value="">جارٍ التحميل…</option></select></label><div class="permission-box"><strong>الصلاحيات</strong>${Object.entries(labels).map(([k,v])=>`<label><input type="checkbox" name="cityPermission" value="${k}" checked> ${v}</label>`).join('')}</div></div><button class="primary">إنشاء المستخدم وحفظ الصلاحيات</button></form><section class="panel city-list"><div class="panel-head"><div><h2>مستخدمو المدن</h2><p>يمكنك تعطيل المستخدم أو إعادة تفعيله.</p></div><button onclick="loadCityUsers()">↻ تحديث</button></div><div id="cityUsersList"><p class="loading">لا توجد بيانات محملة.</p></div></section></div></section>`);
 const codeLabel=document.createElement('label');codeLabel.innerHTML='رمز دخول المشرف<input id="cityUserCode" type="password" minlength="8" required placeholder="8 أحرف على الأقل">';document.querySelector('.permission-box').before(codeLabel);
 const hdr=()=>({'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('khalasaStaffToken')||''}`});
 window.saveAdminToken=()=>{localStorage.setItem('khalasaStaffToken',cityAdminToken.value.trim());loadCityUsers()};
 window.loadCityUsers=async()=>{cityAdminToken.value=localStorage.getItem('khalasaStaffToken')||'';try{const [cr,ur]=await Promise.all([fetch(`${api}/v1/admin/cities`,{headers:hdr()}),fetch(`${api}/v1/admin/city-users`,{headers:hdr()})]);if(!cr.ok||!ur.ok)throw Error();const cities=(await cr.json()).cities||[], users=(await ur.json()).users||[];citySelect.innerHTML=cities.map(x=>`<option value="${esc(x.id)}">${esc(x.governorate)} — ${esc(x.name)}</option>`).join('');cityApiNote.className='api-note ok';cityApiNote.textContent='متصل بقاعدة البيانات — العزل والصلاحيات مطبقان على الخادم.';cityUsersList.innerHTML=users.length?users.map(x=>`<article class="city-user-card"><div><b>${esc(x.full_name)}</b><small>${esc(x.city_name)} · ${esc(x.phone)}</small><small>${esc(Object.entries(x.permissions||{}).filter(([,v])=>v).map(([k])=>labels[k]).join('، '))}</small></div><div class="city-user-actions"><span class="tag ${x.is_active?'active-tag':'trial-tag'}">${x.is_active?'نشط':'معطل'}</span><button class="table-btn" data-user="${esc(x.id)}" data-active="${!x.is_active}">${x.is_active?'تعطيل':'تفعيل'}</button></div></article>`).join(''):'<p class="loading">لا يوجد مستخدمو مدن بعد.</p>';cityUsersList.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>toggleCityUser(b.dataset.user,b.dataset.active==='true',users.find(x=>x.id===b.dataset.user).permissions));}catch(e){cityApiNote.className='api-note';cityApiNote.textContent='تعذر الاتصال. تأكد من رمز دخول المدير ومن نشر تحديث الخادم.';}};
 window.createCityUser=async e=>{e.preventDefault();const permissions={};document.querySelectorAll('[name=cityPermission]').forEach(x=>permissions[x.value]=x.checked);const r=await fetch(`${api}/v1/admin/city-users`,{method:'POST',headers:hdr(),body:JSON.stringify({fullName:cityUserName.value.trim(),phone:cityUserPhone.value.trim(),cityId:citySelect.value,accessCode:cityUserCode.value,permissions})});if(!r.ok)return toast('تعذر إنشاء المستخدم؛ تحقق من البيانات ورمز الدخول');e.target.reset();toast('تم إنشاء مستخدم المدينة');loadCityUsers()};
 window.toggleCityUser=async(id,isActive,permissions)=>{const r=await fetch(`${api}/v1/admin/city-users/${id}`,{method:'PATCH',headers:hdr(),body:JSON.stringify({isActive,permissions})});toast(r.ok?'تم تحديث حالة المستخدم':'تعذر تحديث المستخدم');if(r.ok)loadCityUsers()};
})();
